18	import { useToast } from '@/hooks/use-toast';
19	import { forceToggleAttendance, updateAllUserDisplayNames, updateUserCardId } from '@/app/actions';
20	import { Tables } from '@/lib/types';
21	import { User } from '@supabase/supabase-js';
22	import { convertGenerationToGrade } from '@/lib/utils';
23	import {
24	  AlertDialog,
25	  AlertDialogAction,
26	  AlertDialogCancel,
27	  AlertDialogContent,
28	  AlertDialogDescription,
29	  AlertDialogFooter,
30	  AlertDialogHeader,
31	  AlertDialogTitle,
32	  AlertDialogTrigger,
33	} from "@/components/ui/alert-dialog"
34	import {
35	  Dialog,
36	  DialogContent,
37	  DialogDescription,
38	  DialogFooter,
39	  DialogHeader,
40	  DialogTitle,
41	  DialogTrigger,
42	} from "@/components/ui/dialog"
43	import { Label } from "@/components/ui/label"
44	import {
45	  Select,
46	  SelectContent,
47	  SelectItem,
48	  SelectTrigger,
49	  SelectValue,
50	} from "@/components/ui/select"
51	import { Checkbox } from "@/components/ui/checkbox"
52	import Link from "next/link";
53	
54	type UserWithDetails = {
55	    id: string;
56	    display_name: string;
57	    card_id: string | null;
58	    team_name: string | null;
59	    team_id: string | null;
60	    generation: number;
61	    is_admin: boolean;
62	    latest_attendance_type: string | null;
63	    latest_timestamp: string | null;
64	    deleted_at: string | null;
65	    student_number: string | null;
66	    status: number;
67	};
68	
69	type SortKey = keyof UserWithDetails;
70	type SortDirection = 'asc' | 'desc';
71	
72	interface UsersTabProps {
73	    users: UserWithDetails[];
74	    teams: Tables<'member', 'teams'>[];
75	    currentUser: User;
76	}
77	
78	type AttendanceStatus = 'not_clocked_in' | 'clocked_in' | 'clocked_out' | 'all';
79	type UserStatus = 0 | 1 | 2 | null; // 0: 中学生, 1: 高校生, 2: OB/OG
80	type StatusFilter = UserStatus | 'all' | 'active'; // 'active' = OB/OG以外（中学生・高校生）
81	
82	const SortableHeader = ({
83	  children,
84	  sortKey,
85	  currentSort,
86	  onSort,
87	}: {
88	  children: React.ReactNode;
89	  sortKey: SortKey;
90	  currentSort: { key: SortKey; direction: SortDirection };
91	  onSort: (key: SortKey) => void;
92	}) => {
93	  const isSorted = currentSort.key === sortKey;
94	  return (
95	    <TableHead onClick={() => onSort(sortKey)} className="cursor-pointer hover:bg-muted/50">
96	      <div className="flex items-center gap-2">
97	        {children}
98	        {isSorted && (
99	          <ArrowUpDown
100	            className={`h-4 w-4 transition-transform ${
101	              currentSort.direction === 'desc' ? 'rotate-180' : ''
102	            }`}
103	          />
104	        )}
105	        {!isSorted && <ArrowUpDown className="h-4 w-4 text-muted-foreground/50" />}
106	      </div>
107	    </TableHead>
108	  );
109	};
110	
111	
112	// ユーザーの現在の出勤状態を判定する関数
113	const getAttendanceStatus = (latestType: string | null, latestTimestamp: string | null): AttendanceStatus => {
114	    if (!latestTimestamp) return 'not_clocked_in';
115	    
116	    const now = new Date();
117	    const latest = new Date(latestTimestamp);
118	    const todayMidnight = new Date(now);
119	    todayMidnight.setHours(0, 0, 0, 0);
120	    
121	    // 最後の記録が今日の0:00より前の場合、まだ出勤していない
122	    if (latest < todayMidnight) {
123	        return 'not_clocked_in';
124	    }
125	    
126	    // 今日の記録がある場合
127	    if (latestType === 'in') {
128	        return 'clocked_in'; // 出勤中
129	    } else {
130	        return 'clocked_out'; // 退勤済み
131	    }
132	};
133	
134	const getStatusLabel = (status: number): string => {
135	    switch (status) {
136	        case 0: return '中学生';
137	        case 1: return '高校生';
138	        case 2: return 'OB/OG';
139	        default: return '不明';
140	    }
141	};
142	
143	const getAttendanceStatusLabel = (status: AttendanceStatus): string => {
144	    switch (status) {
145	        case 'not_clocked_in': return '未出勤';
146	        case 'clocked_in': return '出勤中';
147	        case 'clocked_out': return '退勤済み';
148	        default: return '全て';
149	    }
150	};
151	
152	const getAttendanceStatusBadgeVariant = (status: AttendanceStatus): "default" | "secondary" | "destructive" | "outline" => {
153	    switch (status) {
154	        case 'not_clocked_in': return 'outline';
155	        case 'clocked_in': return 'default';
156	        case 'clocked_out': return 'secondary';
157	        default: return 'outline';
158	    }
159	};
160	
161	export default function UsersTab({ users: initialUsers, teams, currentUser }: UsersTabProps) {
162	    const { toast } = useToast();
163	    const [searchTerm, setSearchTerm] = useState('');
164	    const [sort, setSort] = useState<{ key: SortKey; direction: SortDirection }>({ key: 'display_name', direction: 'asc' });
165	    const [isToggling, startToggleTransition] = useTransition();
166	    const [isUpdatingNames, startUpdatingNamesTransition] = useTransition();
167	    const [isUpdatingCardId, startUpdatingCardIdTransition] = useTransition();
168	    const [editingUser, setEditingUser] = useState<{ id: string; currentCardId: string } | null>(null);
169	    const [newCardId, setNewCardId] = useState('');
170	    
171	    // フィルター状態
172	    const [filterStatus, setFilterStatus] = useState<StatusFilter>('active'); // デフォルトでOB/OG除外
173	    const [filterAttendance, setFilterAttendance] = useState<AttendanceStatus>('all'); // 出勤状態
174	    const [filterHasCardId, setFilterHasCardId] = useState<boolean | 'all'>('all'); // カードID有無
175	    const [showFilters, setShowFilters] = useState(false);
176	
177	    const handleForceToggle = (userId: string) => {
178	        startToggleTransition(async () => {
179	            const result = await forceToggleAttendance(userId);
180	            if (result.success) {
181	                toast({ title: "成功", description: result.message });
182	            } else {
183	                toast({ variant: "destructive", title: "エラー", description: result.message });
184	            }
185	        });
186	    }
187	
188	    const handleUpdateAllNames = () => {
189	        startUpdatingNamesTransition(async () => {
190	            const result = await updateAllUserDisplayNames();
191	            toast({
192	                title: result.success ? "成功" : "エラー",
193	                description: result.message,
194	                variant: result.success ? "default" : "destructive",
195	            });
196	        });
197	    };
198	
199	    const handleUpdateCardId = (userId: string) => {
200	        startUpdatingCardIdTransition(async () => {
201	            const result = await updateUserCardId(userId, newCardId);
202	            toast({
203	                title: result.success ? "成功" : "エラー",
204	                description: result.message,
205	                variant: result.success ? "default" : "destructive",
206	            });
207	            if (result.success) {
208	                setEditingUser(null);
209	                setNewCardId('');
210	            }
211	        });
212	    };
213	
214	    const handleSort = (key: SortKey) => {
215	        setSort(prevSort => ({
216	            key,
217	            direction: prevSort.key === key && prevSort.direction === 'asc' ? 'desc' : 'asc',
218	        }));
219	    };
220	
221	    const sortedAndFilteredUsers = useMemo(() => {
222	        let filtered = initialUsers.filter(user => {
223	            // テキスト検索
224	            const matchesSearch = user.display_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
225	                (user.card_id && user.card_id.toLowerCase().includes(searchTerm.toLowerCase())) ||
226	                (user.student_number && user.student_number.toLowerCase().includes(searchTerm.toLowerCase()));
227	            
228	            if (!matchesSearch) return false;
229	            
230	            // ステータスフィルター (中学生/高校生/OB/OG)
231	            if (filterStatus === 'active') {
232	                // OB/OG(status === 2)を除外
233	                if (user.status === 2) return false;
234	            } else if (filterStatus !== 'all' && user.status !== filterStatus) {
235	                return false;
236	            }
237	            
238	            // 出勤状態フィルター
239	            if (filterAttendance !== 'all') {
240	                const attendanceStatus = getAttendanceStatus(user.latest_attendance_type, user.latest_timestamp);
241	                if (attendanceStatus !== filterAttendance) return false;
242	            }
243	            
244	            // カードID有無フィルター
245	            if (filterHasCardId !== 'all') {
246	                const hasCardId = !!user.card_id;
247	                if (hasCardId !== filterHasCardId) return false;
248	            }
249	            
250	            return true;
251	        });
252	
253	        filtered.sort((a, b) => {
254	            const key = sort.key;
255	            let valA: any = a[key as keyof UserWithDetails];
256	            let valB: any = b[key as keyof UserWithDetails];
257	            
258	            if (typeof valA === 'string' && typeof valB === 'string') {
259	                valA = valA.toLowerCase();
260	                valB = valB.toLowerCase();
261	            }
262	
263	            if (valA < valB) return sort.direction === 'asc' ? -1 : 1;
264	            if (valA > valB) return sort.direction === 'asc' ? 1 : -1;
265	            return 0;
266	        });
267	        
268	        return filtered;
269	    }, [initialUsers, searchTerm, sort, filterStatus, filterAttendance, filterHasCardId]);
270	
271	  return (
272	     <Card>
273	            <CardHeader>
274	                <CardTitle>ユーザー管理</CardTitle>
275	                <CardDescription>
276	                    ユーザー情報の表示と、手動での出退勤操作を行います。({sortedAndFilteredUsers.length}名表示中 / 全{initialUsers.length}名)
277	                </CardDescription>
278	            </CardHeader>
279	            <CardContent>
280	            <div className="mb-4 space-y-4">
281	                <div className="flex items-center gap-4">
282	                    <div className="relative flex-grow">
283	                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
284	                        <Input
285	                            placeholder="表示名、カードID、学籍番号で検索..."
286	                            value={searchTerm}
287	                            onChange={(e) => setSearchTerm(e.target.value)}
288	                            className="pl-9"
289	                        />
290	                    </div>
291	                    <Button variant="outline" onClick={() => setShowFilters(!showFilters)}>
292	                        <Filter className="mr-2 h-4 w-4" />
293	                        {showFilters ? 'フィルターを隠す' : 'フィルター'}
294	                    </Button>
295	                    <AlertDialog>
296	                        <AlertDialogTrigger asChild>
297	                            <Button variant="outline">
298	                                <RefreshCw className={`mr-2 h-4 w-4 ${isUpdatingNames ? 'animate-spin' : ''}`} />
299	                                表示名を更新
300	                            </Button>
301	                        </AlertDialogTrigger>
302	                        <AlertDialogContent>
303	                            <AlertDialogHeader>
304	                            <AlertDialogTitle>全ユーザーの表示名を更新しますか？</AlertDialogTitle>
305	                            <AlertDialogDescription>
306	                                Discordサーバーのニックネーム（本名）をAPI経由で取得し、このシステムの全ユーザーの表示名を上書きします。この操作は時間がかかる場合があります。
307	                            </AlertDialogDescription>
308	                            </AlertDialogHeader>
309	                            <AlertDialogFooter>
310	                            <AlertDialogCancel>キャンセル</AlertDialogCancel>
311	                            <AlertDialogAction onClick={handleUpdateAllNames} disabled={isUpdatingNames}>
312	                                {isUpdatingNames ? '更新中...' : '実行する'}
313	                            </AlertDialogAction>
314	                            </AlertDialogFooter>
315	                        </AlertDialogContent>
316	                    </AlertDialog>
317	                </div>
318	                
319	                {showFilters && (
320	                    <Card className="p-4">
321	                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
322	                            <div className="space-y-2">
323	                                <Label>ステータス</Label>
324	                                <Select 
325	                                    value={filterStatus === 'all' ? 'all' : filterStatus === 'active' ? 'active' : String(filterStatus)} 
326	                                    onValueChange={(val) => {
327	                                        if (val === 'all') setFilterStatus('all');
328	                                        else if (val === 'active') setFilterStatus('active');
329	                                        else setFilterStatus(Number(val) as UserStatus);
330	                                    }}
331	                                >
332	                                    <SelectTrigger>
333	                                        <SelectValue />
334	                                    </SelectTrigger>
335	                                    <SelectContent>
336	                                        <SelectItem value="active">現役部員のみ</SelectItem>
337	                                        <SelectItem value="all">全て</SelectItem>
338	                                        <SelectItem value="0">中学生</SelectItem>
339	                                        <SelectItem value="1">高校生</SelectItem>
340	                                        <SelectItem value="2">OB/OG</SelectItem>
341	                                    </SelectContent>
342	                                </Select>
343	                            </div>
344	                            
345	                            <div className="space-y-2">
346	                                <Label>出勤状態</Label>
347	                                <Select value={filterAttendance} onValueChange={(val) => setFilterAttendance(val as AttendanceStatus)}>
348	                                    <SelectTrigger>
349	                                        <SelectValue />
350	                                    </SelectTrigger>
351	                                    <SelectContent>
352	                                        <SelectItem value="all">全て</SelectItem>
353	                                        <SelectItem value="not_clocked_in">未出勤</SelectItem>
354	                                        <SelectItem value="clocked_in">出勤中</SelectItem>
355	                                        <SelectItem value="clocked_out">退勤済み</SelectItem>
356	                                    </SelectContent>
357	                                </Select>
358	                            </div>
359	                            
360	                            <div className="space-y-2">
361	                                <Label>カードID</Label>
362	                                <Select value={filterHasCardId === 'all' ? 'all' : String(filterHasCardId)} onValueChange={(val) => setFilterHasCardId(val === 'all' ? 'all' : val === 'true')}>
363	                                    <SelectTrigger>
364	                                        <SelectValue />
365	                                    </SelectTrigger>
366	                                    <SelectContent>
367	                                        <SelectItem value="all">全て</SelectItem>
368	                                        <SelectItem value="true">登録済み</SelectItem>
369	                                        <SelectItem value="false">未登録</SelectItem>
370	                                    </SelectContent>
371	                                </Select>
372	                            </div>
373	                        </div>
374	                        
375	                        <div className="mt-4 flex justify-end">
376	                            <Button variant="ghost" size="sm" onClick={() => {
377	                                setFilterStatus('active');
378	                                setFilterAttendance('all');
379	                                setFilterHasCardId('all');
380	                            }}>
381	                                フィルターをリセット
382	                            </Button>
383	                        </div>
384	                    </Card>
385	                )}
386	            </div>
387	            <Table>
388	                <TableHeader>
389	                    <TableRow>
390	                        <SortableHeader sortKey="display_name" currentSort={sort} onSort={handleSort}>表示名</SortableHeader>
391	                        <SortableHeader sortKey="generation" currentSort={sort} onSort={handleSort}>学年/期生</SortableHeader>
392	                        <SortableHeader sortKey="status" currentSort={sort} onSort={handleSort}>ステータス</SortableHeader>
393	                        <SortableHeader sortKey="latest_attendance_type" currentSort={sort} onSort={handleSort}>出勤状態</SortableHeader>
394	                        <SortableHeader sortKey="card_id" currentSort={sort} onSort={handleSort}>カードID</SortableHeader>
395	                        <TableHead>アクション</TableHead>
396	                    </TableRow>
397	                </TableHeader>
398	                <TableBody>
399	                    {sortedAndFilteredUsers?.map(user => {
400	                        const attendanceStatus = getAttendanceStatus(user.latest_attendance_type, user.latest_timestamp);
401	                        return (
402	                        <TableRow key={user.id} className={isToggling ? 'opacity-50' : ''}>
403	                            <TableCell className="font-medium">{user.display_name}</TableCell>
404	                            <TableCell>{convertGenerationToGrade(user.generation)}</TableCell>
405	                            <TableCell>
406	                                <Badge variant="outline">{getStatusLabel(user.status)}</Badge>
407	                            </TableCell>
408	                            <TableCell>
409	                                <Badge variant={getAttendanceStatusBadgeVariant(attendanceStatus)}>
410	                                    {getAttendanceStatusLabel(attendanceStatus)}
411	                                </Badge>
412	                            </TableCell>
413	                            <TableCell className="font-mono text-sm">{user.card_id || <span className="text-muted-foreground">未登録</span>}</TableCell>
414	                            <TableCell className="space-x-2">
415	                                <div className="flex items-center gap-2">
416	                                    <Button size="sm" variant="outline" asChild>
417	                                        <Link href={`/admin/users/${user.id}`}>
418	                                            <Eye className="h-4 w-4 mr-1" />
419	                                            詳細
420	                                        </Link>
421	                                    </Button>
422	                                    <Dialog open={editingUser?.id === user.id} onOpenChange={(open) => {
423	                                        if (!open) {
424	                                            setEditingUser(null);
425	                                            setNewCardId('');
426	                                        }
427	                                    }}>
428	                                        <DialogTrigger asChild>
429	                                            <Button size="sm" variant="outline" onClick={() => {
430	                                                setEditingUser({ id: user.id, currentCardId: user.card_id || '' });
431	                                                setNewCardId(user.card_id || '');
432	                                            }}>
433	                                                <Edit className="h-4 w-4 mr-1" />
434	                                                カードID
435	                                            </Button>
436	                                        </DialogTrigger>
437	                                        <DialogContent>
438	                                            <DialogHeader>
439	                                                <DialogTitle>カードIDを変更</DialogTitle>
440	                                                <DialogDescription>
441	                                                    {user.display_name} さんのカードIDを変更します
442	                                                </DialogDescription>
443	                                            </DialogHeader>
444	                                            <div className="grid gap-4 py-4">
445	                                                <div className="grid gap-2">
446	                                                    <Label htmlFor="cardId">新しいカードID</Label>
447	                                                    <Input
448	                                                        id="cardId"
449	                                                        value={newCardId}
450	                                                        onChange={(e) => setNewCardId(e.target.value)}
451	                                                        placeholder="カードIDを入力"
452	                                                        className="font-mono"
453	                                                    />
454	                                                    <p className="text-sm text-muted-foreground">
455	                                                        現在: <code className="font-mono">{user.card_id || '未設定'}</code>
456	                                                    </p>
457	                                                </div>
458	                                            </div>
459	                                            <DialogFooter>
460	                                                <Button variant="outline" onClick={() => {
461	                                                    setEditingUser(null);
462	                                                    setNewCardId('');
463	                                                }}>
464	                                                    キャンセル
465	                                                </Button>
466	                                                <Button onClick={() => handleUpdateCardId(user.id)} disabled={isUpdatingCardId || !newCardId}>
467	                                                    {isUpdatingCardId ? '更新中...' : '更新'}
468	                                                </Button>
469	                                            </DialogFooter>
470	                                        </DialogContent>
471	                                    </Dialog>
472	                                    <Button size="sm" variant={attendanceStatus === 'clocked_in' ? 'destructive' : 'default'} onClick={() => handleForceToggle(user.id)} disabled={isToggling}>
473	                                        {attendanceStatus === 'clocked_in' ? '強制退勤' : '強制出勤'}
474	                                    </Button>
475	                                </div>
476	                            </TableCell>
477	                        </TableRow>
478	                        );
479	                    })}
480	                </TableBody>
481	            </Table>
482	            </CardContent>
483	        </Card>
484	  )
485	}
